072390283\",\"skill_name\":\"canva-branded-presentation\",\"contents\":[],\"allow_implicit_invocation\":true}},{\"server\":\"codex_apps\",\"uri\":\"skill://plugin_connector_68df33b1a2d081918778431a9cfca8ba/canva-bulk-create\",\"name\":\"plugin_connector_68df33b1a2d081918778431a9cfca8ba/canva-bulk-create\",\"title\":\"canva-bulk-create\",\"description\":\"Bulk-create Canva designs from tabular data using a brand template with autofill fields, producing one design per row. Use when users say \\\"bulk create designs from this CSV\\\", \\\"generate one design per row\\\", \\\"create a design for each product\\\", \\\"batch generate from a template\\\", or \\\"autofill a template from a spreadsheet\\\". Accepts any tabular data source — uploaded files, pasted tables, JSON, or URLs.\",\"mimeType\":\"mcp/skill\",\"_meta\":{\"plugin_id\":\"plugin_connector_68df33b1a2d081918778431a9cfca8ba\",\"plugin_name\":\"canva\",\"plugin_release_id\":\"pluginrel_d575a12fb6c08191947fd0c8515cde27\",\"plugin_release_skill_id\":\"pluginrsk_6a6c49c028048191919a8af8ec0a0569\",\"skill_name\":\"canva-bulk-create\",\"contents\":[],\"allow_implicit_invocation\":true}},{\"server\":\"codex_apps\",\"uri\":\"skill://plugin_connector_68df33b1a2d081918778431a9cfca8ba/canva-translate-design\",\"name\":\"plugin_connector_68df33b1a2d081918778431a9cfca8ba/canva-translate-design\",\"title\":\"canva-translate-design\",\"description\":\"Translate all text in a Canva design to another language, creating a translated copy. Faster than manually copying and editing each text box in Canva's editor. Use when users say \\\"translate my design to [language]\\\", \\\"make a Spanish/French/etc version\\\", or \\\"localize my Canva design\\\".\",\"mimeType\":\"mcp/skill\",\"_meta\":{\"plugin_id\":\"plugin_connector_68df33b1a2d081918778431a9cfca8ba\",\"plugin_name\":\"canva\",\"plugin_release_id\":\"pluginrel_d575a12fb6c08191947fd0c8515cde27\",\"plugin_release_skill_id\":\"pluginrsk_6a6c49c069008191adc16153cb86b667\",\"skill_name\":\"canva-translate-design\",\"contents\":[],\"allow_implicit_invocation\":true}},{\"server\":\"codex_apps\",\"uri\":\"skill://plugin_connector_68df33b1a2d081918778431a9cfca8ba/canva-edit-design\",\"name\":\"plugin_connector_68df33b1a2d081918778431a9cfca8ba/canva-edit-design\",\"title\":\"canva-edit-design\",\"description\":\"Make edits to an existing Canva design — change or fix text, replace/insert/delete images and videos, reformat text (size, weight, style, color, alignment, lists, line height), reposition or resize elements, and update the title. Use when the user wants to change, edit, update, fix, translate, replace, or reformat content in a specific Canva design. This is the safe edit engine that other Canva skills (e.g. implement-feedback) build on.\",\"mimeType\":\"mcp/skill\",\"_meta\":{\"plugin_id\":\"plugin_connector_68df33b1a2d081918778431a9cfca8ba\",\"plugin_name\":\"canva\",\"plugin_release_id\":\"pluginrel_d575a12fb6c08191947fd0c8515cde27\",\"plugin_release_skill_id\":\"pluginrsk_6a6c49c0a7108191a6c21bbc5ded49a7\",\"skill_name\":\"canva-edit-design\",\"contents\":[],\"allow_implicit_invocation\":true}},{\"server\":\"codex_apps\",\"uri\":\"skill://plugin_connector_68df33b1a2d081918778431a9cfca8ba/canva-design-feedback\",\"name\":\"plugin_connector_68df33b1a2d081918778431a9cfca8ba/canva-design-feedback\",\"title\":\"canva-design-feedback\",\"description\":\"Read a Canva design and return structured, actionable design feedback — visual hierarchy, copy/messaging, layout & spacing, consistency, readability, and accessibility. Read-only; makes no changes to the design. Use when the user asks to \\\"review my design\\\", \\\"give me feedback on this\\\", \\\"critique my deck/poster/flyer\\\", \\\"how can I improve this design\\\", or \\\"what's wrong with this slide\\\".\",\"mimeType\":\"mcp/skill\",\"_meta\":{\"plugin_id\":\"plugin_connector_68df33b1a2d081918778431a9cfca8ba\",\"plugin_name\":\"canva\",\"plugin_release_id\":\"pluginrel_d575a12fb6